const STORY_DATA = [
 {title:'Creation and the Garden',ref:'Genesis 1–3',image:'creation-people.jpg',color:'#d9edf0',summary:'God made light, sky, land, plants, animals, and people. In the garden, Adam and Eve faced a choice when the serpent spoke to them.',message:'God made the world and people, and invites us to trust and follow him.',activity:'Make a five-scene story strip using pictures, paper, or drawings.',frames:[{title:'God makes light',ref:'Genesis 1:3–5',text:'God said, “Let there be light.” Light and darkness each had their place.',image:'creation-light.jpg'},{title:'Sky and waters',ref:'Genesis 1:6–8',text:'God made the wide sky and gathered the waters below it.',image:'creation-sky.jpg'},{title:'Land and growing things',ref:'Genesis 1:9–13',text:'Dry ground appeared, and plants and trees grew across the land.',image:'creation-land.jpg'},{title:'Adam and Eve',ref:'Genesis 1:26–31; 2:18–25',text:'God made people, Adam and Eve, and gave them a home in the garden.',image:'creation-people.jpg'},{title:'A choice in the garden',ref:'Genesis 3:1–13',text:'The serpent spoke to Eve. Adam and Eve chose to eat the fruit, and they hid from God.',image:'creation-5.svg'}]},
 {title:'Noah and the Ark',ref:'Genesis 6–9',image:'noah.svg',color:'#dcecf0',summary:'Noah trusted God and built an ark. God kept Noah’s family and the animals safe through the flood.',message:'We can trust God to keep his promises.',activity:'Pair animal pictures and march two by two around the room.'},
 {title:'Moses in the Basket',ref:'Exodus 2:1–10',image:'moses.svg',color:'#e6f0e2',summary:'Baby Moses was placed in a basket on the river and was safely found by Pharaoh’s daughter.',message:'God cared for Moses, and God cares for us.',activity:'Make a small paper basket and decorate it with reeds.'},
 {title:'David and Goliath',ref:'1 Samuel 17',image:'david.svg',color:'#e9e6d8',summary:'Young David trusted God and bravely faced the giant Goliath with a sling and a stone.',message:'With God’s help, we can be brave when something feels big.',activity:'Toss soft beanbags at a stack of paper cups.'},
 {title:'Daniel and the Lions',ref:'Daniel 6',image:'daniel.svg',color:'#f5e8cd',summary:'Daniel kept praying to God. God protected him in the lions’ den.',message:'We can keep talking to God, even when life is difficult.',activity:'Make a lion face from a paper plate and yarn.'},
 {title:'Jonah and the Big Fish',ref:'Jonah 1–3',image:'jonah.svg',color:'#dcecf0',summary:'Jonah ran from the task God gave him, but God gave him another chance to obey.',message:'God gives us second chances and helps us make things right.',activity:'Move like a fish, then act out Jonah’s journey.'},
 {title:'Jesus Calms the Storm',ref:'Mark 4:35–41',image:'storm.svg',color:'#e5e8f4',summary:'A storm frightened the disciples, but Jesus calmed the wind and waves.',message:'Jesus is with us when we feel afraid.',activity:'Blow through straws to race cotton-ball boats in a tray.'},
 {title:'The Good Samaritan',ref:'Luke 10:25–37',image:'samaritan.svg',color:'#f5e4df',summary:'A Samaritan stopped to help an injured stranger when others passed by.',message:'Love your neighbor by showing kindness to everyone.',activity:'Draw a kindness card for someone who needs encouragement.'},
 {title:'The Lost Sheep',ref:'Luke 15:1–7',image:'sheep.svg',color:'#e8efe2',summary:'A shepherd searched for one lost sheep and joyfully brought it home.',message:'God knows each of us and never forgets us.',activity:'Hide a toy sheep and take turns finding it.'},
 {title:'Jesus Feeds the Five Thousand',ref:'John 6:1–14',image:'loaves.svg',color:'#f6edda',summary:'A boy shared his five loaves and two fish. Jesus used them to feed a huge crowd.',message:'Small gifts can make a big difference when we share.',activity:'Make a paper basket with five loaves and two fish.'},
 {title:'The Nativity',ref:'Luke 2:1–20',image:'nativity.svg',color:'#f2e8d5',summary:'Jesus was born in Bethlehem. Angels shared the good news with shepherds, who came to see him.',message:'Jesus is God’s gift of love to the world.',activity:'Create a paper star ornament.'},
 {title:'The Resurrection',ref:'Matthew 28:1–10',image:'resurrection.svg',color:'#f0e4ed',summary:'The women found Jesus’ tomb empty. Jesus was alive, just as he had promised.',message:'Jesus is alive, and his love gives us hope.',activity:'Make a paper garden with flowers and an empty-tomb scene.'}
];
const KEY='brightsteps-v1';
const AGE_GROUPS=['Little Ones (2–3)','Preschool (4–5)','Primary (6–8)','Preteen (9–12)','Unassigned'];
let db=JSON.parse(localStorage.getItem(KEY)||'{"children":[],"lessons":[],"attendance":[]}');
db.children ||= []; db.lessons ||= []; db.attendance ||= []; db.customStories ||= []; db.offlineStories ||= []; db.sessions ||= []; db.attendanceRecords ||= []; db.workSamples ||= [];
db.children.forEach((c,i)=>{c.id ||= `child-${i+1}`;c.ageGroup ||= getAgeGroup(c)});
if(!db.attendanceRecords.length && db.attendance.length){db.attendance.forEach(a=>{let session={id:`legacy-${a.date}`,date:a.date,title:'Class session',lessonId:'',completed:true};db.sessions.push(session);let marks={};db.children.forEach(c=>marks[c.id]={status:(a.present||[]).includes(c.id)?'present':'absent',remark:''});db.attendanceRecords.push({sessionId:session.id,date:a.date,marks})})}
db.attendance=db.attendanceRecords;
db.lessons.forEach(l=>{let s=db.sessions.find(x=>x.date===l.date);if(!s)db.sessions.push({id:`lesson-${l.id}`,date:l.date,title:'Class session',lessonId:l.id,completed:false});else if(!s.lessonId)s.lessonId=l.id});
let page='home',storyFilter='',calendarMonth=new Date(),selectedCalendarDate=dateISO(),selectedSessionId='',reportDate=dateISO(),guardianChildId='';
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){console.error(e);toast('Device storage is full. Export a backup and remove older pictures.') }}
function dateISO(d=new Date()){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function niceDate(s){return s?new Date(s+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):''}
function initials(s){return s.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)}
function getAgeGroup(c){let n=Number(c.age);return n>0&&n<=3?'Little Ones (2–3)':n<=5&&n>0?'Preschool (4–5)':n<=8&&n>0?'Primary (6–8)':n<=12&&n>0?'Preteen (9–12)':'Unassigned'}
function sessionRecord(id){return db.attendanceRecords.find(r=>r.sessionId===id)}
function sessionMark(sessionId,childId){let r=sessionRecord(sessionId);return r?.marks?.[childId]||{status:'absent',remark:''}}
function sessionLesson(s){return db.lessons.find(l=>l.id===s.lessonId)}
function newId(){return crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`}
function allStories(){return [...STORY_DATA.map((s,i)=>({...s,key:'b'+i,custom:false})),...db.customStories.map((s,i)=>({...s,key:'c'+i,custom:true,image:s.frames?.[0]?.image||s.image||'custom.svg'}))]}
function getStory(key){return allStories().find(s=>s.key===key)}
function storyImg(s){return s.image?.startsWith('data:')?s.image:`images/${s.image||'custom.svg'}`}
const titles={home:'A little progress, every week.',calendar:'A gentle plan for what’s ahead.',attendance:'A welcoming classroom starts here.',lessons:'Every week has a story.',stories:'Find a story to share.',children:'Get to know your class.',reports:'See how the class is doing.',guardian:'A family view of attendance.'};
function go(p){page=p;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===p));document.getElementById('pageTitle').textContent=titles[p];render()}
function render(){let v=document.getElementById('view');if(page==='home')v.innerHTML=homeView();if(page==='children')v.innerHTML=childrenView();if(page==='lessons')v.innerHTML=lessonsView();if(page==='attendance')v.innerHTML=attendanceView();if(page==='stories')v.innerHTML=storiesView();if(page==='calendar')v.innerHTML=calendarView();if(page==='reports')v.innerHTML=reportsView();if(page==='guardian')v.innerHTML=guardianView();wireView()}
function homeView(){let upcoming=[...db.lessons].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);let latest=db.attendance.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];let pct=latest&&latest.present.length?Math.round(latest.present.length/(db.children.length||latest.present.length)*100):0;return `<div class="welcome"><div><h2>Welcome to your classroom 🌿</h2><p>Keep the little moments of faith, learning, and friendship<br class="desktop-hide"> all in one place.</p></div><div class="welcome-art">📖</div></div><div class="stats"><div class="stat"><div class="stat-top">Children in your class <span class="stat-icon">♡</span></div><div class="stat-num">${db.children.length}</div><div class="stat-note">${db.children.length?'Ready for a new Sunday':'Add children to get started'}</div></div><div class="stat"><div class="stat-top">Lessons recorded <span class="stat-icon">▤</span></div><div class="stat-num">${db.lessons.length}</div><div class="stat-note">Stories and activities together</div></div><div class="stat"><div class="stat-top">Last attendance <span class="stat-icon">✓</span></div><div class="stat-num">${latest?latest.present.length:'—'}</div><div class="stat-note">${latest?`${pct}% of your class · ${niceDate(latest.date)}`:'Take attendance after adding children'}</div></div></div><div class="grid-two"><div class="panel"><div class="panel-head"><h2>Recent lessons</h2><button class="text-button" data-go="lessons">See all →</button></div>${upcoming.length?upcoming.map(l=>lessonRow(l)).join(''):'<div class="empty">Your lesson notes will appear here.<br><button class="text-button" data-action="addlesson">＋ Add your first lesson</button></div>'}</div><div><div class="panel"><div class="panel-head"><h2>Start with a story</h2><button class="text-button" data-go="stories">Browse all →</button></div>${STORY_DATA.slice(0,3).map((s,i)=>`<div class="story-row"><div class="mini-art"><img src="images/${s.image}" alt="Illustration of ${esc(s.title)}"></div><div class="row-main"><b>${esc(s.title)}</b><small>${esc(s.ref)}</small></div><button class="actions" data-story="b${i}">›</button></div>`).join('')}</div></div></div>`}
function lessonRow(l){return `<div class="lesson-row"><div class="date-tile"><b>${new Date(l.date+'T12:00:00').getDate()}</b><small>${new Date(l.date+'T12:00:00').toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small></div><div class="row-main"><b>${esc(l.title)}</b><small>${esc(l.ref||'Lesson')}${l.activity?' · '+esc(l.activity):''}</small></div><span class="tag">${niceDate(l.date)}</span></div>`}
function childrenView(){let selected=document.getElementById('ageFilter')?.value||'all';let groups=selected==='all'?AGE_GROUPS:[selected];return `<div class="toolbar"><input class="search" id="childSearch" placeholder="Search children…"><select class="secondary" id="ageFilter"><option value="all" ${selected==='all'?'selected':''}>All age groups</option>${AGE_GROUPS.map(g=>`<option ${selected===g?'selected':''}>${g}</option>`).join('')}</select><button class="primary" data-action="addchild">＋ Add child</button></div>${groups.map(g=>{let kids=db.children.filter(c=>(c.ageGroup||getAgeGroup(c))===g);return `<div class="panel age-panel"><div class="panel-head"><h2>${g}</h2><span class="pill">${kids.length} children</span></div>${kids.length?`<div class="table-wrap"><table class="table"><thead><tr><th>CHILD</th><th>AGE</th><th>NOTES</th><th></th></tr></thead><tbody id="childRows">${kids.map(c=>childRow(c)).join('')}</tbody></table></div>`:'<div class="empty">No children in this age group yet.</div>'}</div>`}).join('')}${db.children.length===0?'<div class="panel empty">Add children to create your age-group rosters.</div>':''}`}
function childRow(c){return `<tr data-name="${esc(c.name.toLowerCase())}"><td><div class="person"><span class="avatar">${esc(initials(c.name))}</span><b>${esc(c.name)}</b></div></td><td>${esc(c.age||'—')}</td><td>${esc(c.notes||'—')}</td><td><button class="actions delete" data-delete-child="${esc(c.id)}">Remove</button></td></tr>`}
function lessonsView(){let items=[...db.lessons].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="toolbar"><button class="primary" data-action="addlesson">＋ Add lesson</button><button class="secondary" data-go="calendar">▦ View calendar</button><button class="secondary" data-go="stories">✧ Browse Bible stories</button></div><div class="panel"><div class="panel-head"><h2>Lesson journal <span class="pill">${items.length}</span></h2></div>${items.length?items.map(l=>`<div class="lesson-row"><div class="date-tile"><b>${new Date(l.date+'T12:00:00').getDate()}</b><small>${new Date(l.date+'T12:00:00').toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small></div><div class="row-main"><b>${esc(l.title)}</b><small>${esc(l.ref||'')} ${l.activity?' · Activity: '+esc(l.activity):''}${l.notes?' · '+esc(l.notes):''}</small></div><button class="actions delete" data-delete-lesson="${esc(l.id)}">Remove</button></div>`).join(''):'<div class="empty">Record what you taught and the activity you shared.<br>Choose a Bible story to quickly start a lesson.</div>'}</div>`}
function attendanceView(){let s=db.sessions.find(x=>x.id===selectedSessionId)||db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];if(s)selectedSessionId=s.id;let rec=s?sessionRecord(s.id):null;return `<div class="toolbar"><select id="sessionPicker" class="search"><option value="">Choose a class session…</option>${db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<option value="${esc(x.id)}" ${s?.id===x.id?'selected':''}>${niceDate(x.date)} · ${esc(x.title)}</option>`).join('')}</select><button class="primary" data-action="newsession">＋ New session</button>${s?`<button class="secondary" data-edit-session="${esc(s.id)}">Edit session</button>`:''}</div>${s?`<div class="panel session-banner"><div><span class="eyebrow">${niceDate(s.date)}</span><h2>${esc(s.title)}</h2><p>${sessionLesson(s)?`Lesson: ${esc(sessionLesson(s).title)} · ${esc(sessionLesson(s).ref||'')}`:'No lesson assigned yet.'}</p></div><button class="secondary" data-edit-session="${esc(s.id)}">Assign lesson</button></div><div class="panel"><div class="panel-head"><div class="attendance-title"><h2>Mark attendance</h2><span class="pill" id="attendanceCounts">${rec?Object.values(rec.marks).filter(m=>m.status==='present').length:0} present · ${rec?Object.values(rec.marks).filter(m=>m.status==='late').length:0} late</span></div><button class="text-button" id="markAllPresent">Mark all present</button></div>${db.children.length?AGE_GROUPS.map(g=>{let kids=db.children.filter(c=>(c.ageGroup||getAgeGroup(c))===g);if(!kids.length)return '';return `<h3 class="group-heading">${g} <span>${kids.length}</span></h3><div class="table-wrap"><table class="table attendance-table"><thead><tr><th>CHILD</th><th>STATUS</th><th>REMARK</th></tr></thead><tbody>${kids.map(c=>{let mark=rec?.marks?.[c.id]||{};return `<tr><td><div class="person"><span class="avatar">${esc(initials(c.name))}</span><b>${esc(c.name)}</b></div></td><td><select class="status-select" data-child-status="${esc(c.id)}"><option value="" ${!mark.status?'selected':''}>Choose…</option><option value="present" ${mark.status==='present'?'selected':''}>Present</option><option value="late" ${mark.status==='late'?'selected':''}>Late</option><option value="absent" ${mark.status==='absent'?'selected':''}>Absent</option></select></td><td><input class="remark-input" data-child-remark="${esc(c.id)}" value="${esc(mark.remark||'')}" maxlength="180" placeholder="Optional note or follow-up"></td></tr>`}).join('')}</tbody></table></div>`}).join(''):'<div class="empty">Add children to take attendance.</div>'}<button class="primary" id="saveSessionAttendance">Save this session’s attendance</button></div>`:'<div class="panel empty">Create a class session first. Add its date and lesson, then mark the children present, late, or absent.<br><button class="primary" data-action="newsession">＋ Create a class session</button></div>'}`}
function storyCard(s){let saved=db.offlineStories.includes(s.key);return `<article class="story-card"><div class="story-art"><img src="images/${esc(s.image)}" alt="Illustration: ${esc(s.title)}" loading="lazy"></div><h3>${esc(s.title)}</h3><div class="reference">${esc(s.ref)}</div><p>${esc(s.summary)}</p><div class="big-idea">${esc(s.message||'')}</div><div class="story-actions"><button data-story="${s.key}">Story notes</button><button data-add-story="${s.key}">＋ Lesson</button></div><button class="offline-button ${saved?'saved':''}" data-offline="${s.key}">${saved?'✓ Saved for offline':'↓ Save for offline'}</button></article>`}
function storiesView(){let q=storyFilter.toLowerCase();let items=allStories().filter(s=>(s.title+s.ref+s.summary+s.message).toLowerCase().includes(q));let webq=storyFilter.trim()||'';return `<p class="library-intro">Illustrated Bible story summaries, teaching ideas, and activity prompts. Library pictures work offline after the app’s first load. Tap any story picture to see it full size.</p><div class="toolbar"><input class="search" id="storySearch" placeholder="Search stories or scripture…" value="${esc(storyFilter)}"><button class="secondary" data-action="addstory">＋ Add my own story</button><span class="pill">${items.length} stories</span></div>${items.length?`<div class="story-grid">${items.map(storyCard).join('')}</div>`:`<div class="panel empty">No library story matches “${esc(webq)}”.<br><button class="primary" id="webSearch">Search the web for “${esc(webq||'children’s Bible story')}” ↗</button><p>Online search opens in a new tab. Check the source and read the scripture passage before adding it.</p></div>`}<div class="panel web-search-panel"><div><b>Looking for a story that isn’t listed?</b><small>Search online while connected, then save the story notes here for next time.</small></div><button class="secondary" id="webSearchAlways">Search online ↗</button></div>`}
function calendarView(){let y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-first.getDay()),days=[];for(let i=0;i<42;i++){let d=new Date(start);d.setDate(start.getDate()+i);days.push(d)}let monthLabel=calendarMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'});let cells=days.map(d=>{let iso=dateISO(d), events=db.sessions.filter(s=>s.date===iso);return `<button class="cal-cell ${d.getMonth()!==m?'outside':''} ${iso===selectedCalendarDate?'selected':''}" data-day="${iso}"><span class="cal-num">${d.getDate()}</span>${events.slice(0,2).map(s=>`<span class="cal-event lesson-event">${esc(sessionLesson(s)?.title||s.title)}</span>`).join('')}${events.length>2?`<span class="cal-event">+${events.length-2} more</span>`:''}</button>`}).join('');let sessions=db.sessions.filter(s=>s.date===selectedCalendarDate);return `<div class="toolbar calendar-toolbar"><button class="secondary" id="prevMonth" aria-label="Previous month">←</button><button class="secondary" id="thisMonth">Today</button><button class="secondary" id="nextMonth" aria-label="Next month">→</button><h2>${monthLabel}</h2><button class="primary" id="addCalendarLesson">＋ Plan a session</button></div><div class="panel calendar-panel"><div class="calendar-grid weekday-row">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-grid">${cells}</div></div><div class="panel"><div class="panel-head"><h2>Sessions · ${niceDate(selectedCalendarDate)}</h2><button class="text-button" id="addSelectedLesson">＋ Add session on this date</button></div>${sessions.length?sessions.map(s=>`<div class="lesson-row"><div class="date-tile"><b>${new Date(s.date+'T12:00:00').getDate()}</b><small>SESSION</small></div><div class="row-main"><b>${esc(s.title)}</b><small>${esc(sessionLesson(s)?.title||'No lesson assigned')}</small></div><button class="secondary" data-open-session="${esc(s.id)}">Roster & lesson</button></div>`).join(''):'<div class="empty">No sessions planned for this date. Add a session and choose its lesson.</div>'}</div>`}
function wireView(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));document.querySelectorAll('[data-action="addchild"]').forEach(x=>x.onclick=addChildModal);document.querySelectorAll('[data-action="addlesson"]').forEach(x=>x.onclick=()=>lessonModal());document.querySelectorAll('[data-action="addstory"]').forEach(x=>x.onclick=addStoryModal);document.querySelectorAll('[data-story]').forEach(x=>x.onclick=()=>storyModal(x.dataset.story));document.querySelectorAll('[data-add-story]').forEach(x=>x.onclick=()=>lessonModal(x.dataset.addStory));document.querySelectorAll('[data-offline]').forEach(x=>x.onclick=()=>{let k=x.dataset.offline;if(db.offlineStories.includes(k))db.offlineStories=db.offlineStories.filter(a=>a!==k);else db.offlineStories.push(k);save();render();toast(db.offlineStories.includes(k)?'Story saved for offline use':'Removed from offline saves')});document.querySelectorAll('[data-day]').forEach(x=>x.onclick=()=>{selectedCalendarDate=x.dataset.day;render()});document.querySelectorAll('[data-delete-child]').forEach(x=>x.onclick=()=>{let c=db.children[+x.dataset.deleteChild];if(confirm(`Remove ${c.name} from your class? Existing attendance history will remain.`)){db.children.splice(+x.dataset.deleteChild,1);save();render()}});document.querySelectorAll('[data-delete-lesson]').forEach(x=>x.onclick=()=>{db.lessons=db.lessons.filter(l=>l.id!==x.dataset.deleteLesson);save();render();toast('Lesson removed')});let search=document.getElementById('childSearch');if(search)search.oninput=()=>document.querySelectorAll('#childRows tr').forEach(r=>r.hidden=!r.dataset.name.includes(search.value.toLowerCase()));let ss=document.getElementById('storySearch');if(ss)ss.oninput=()=>{storyFilter=ss.value;let p=ss.selectionStart;render();let n=document.getElementById('storySearch');n.focus();n.setSelectionRange(p,p)};let date=document.getElementById('attDate');if(date)date.onchange=render;document.querySelectorAll('.present-check').forEach(c=>c.onchange=()=>{document.getElementById('presentCount').textContent=`${document.querySelectorAll('.present-check:checked').length} present`});let all=document.getElementById('selectAll');if(all)all.onclick=()=>{document.querySelectorAll('.present-check').forEach(c=>c.checked=true);document.getElementById('presentCount').textContent=`${db.children.length} present`};let saveAtt=document.getElementById('saveAttendance');if(saveAtt)saveAtt.onclick=()=>{let d=document.getElementById('attDate').value;let present=[...document.querySelectorAll('.present-check:checked')].map(c=>c.dataset.id);let old=db.attendance.find(a=>a.date===d);if(old)old.present=present;else db.attendance.push({date:d,present});save();render();toast('Attendance saved')};document.getElementById('webSearch')?.addEventListener('click',()=>openSearch(storyFilter));document.getElementById('webSearchAlways')?.addEventListener('click',()=>openSearch(storyFilter));document.getElementById('prevMonth')?.addEventListener('click',()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);render()});document.getElementById('nextMonth')?.addEventListener('click',()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);render()});document.getElementById('thisMonth')?.addEventListener('click',()=>{calendarMonth=new Date();selectedCalendarDate=dateISO();render()});document.getElementById('addCalendarLesson')?.addEventListener('click',()=>lessonModal(null,selectedCalendarDate));document.getElementById('addSelectedLesson')?.addEventListener('click',()=>lessonModal(null,selectedCalendarDate));document.getElementById('openAttDate')?.addEventListener('click',()=>{go('attendance');document.getElementById('attDate').value=selectedCalendarDate;render()})}
function openSearch(q){let term=(q||'children Bible story').trim()+' children Bible story';window.open('https://www.google.com/search?q='+encodeURIComponent(term),'_blank','noopener,noreferrer')}
function showModal(title,body,submitLabel,submit){let root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal"><h2>${title}</h2><form id="modalForm">${body}<div class="modal-actions"><button type="button" class="secondary" id="cancelModal">Cancel</button><button class="primary">${submitLabel}</button></div></form></div></div>`;root.querySelector('#cancelModal').onclick=()=>root.innerHTML='';root.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''};root.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();if(submit(new FormData(e.target))!==false){root.innerHTML='';save();render()}}}
function addChildModal(){showModal('Add a child',`<div class="field"><label>Child’s name *</label><input name="name" required maxlength="70" placeholder="First and last name"></div><div class="form-grid"><div class="field"><label>Age (optional)</label><input name="age" type="number" min="1" max="18" placeholder="e.g. 7"></div><div class="field"><label>Notes (optional)</label><input name="notes" maxlength="100" placeholder="Allergy, group…"></div></div>`,'Add child',f=>{db.children.push({id:crypto.randomUUID(),name:f.get('name').trim(),age:f.get('age'),notes:f.get('notes').trim()});toast('Child added')})}
function lessonModal(storyKey=null,presetDate=null){let s=storyKey?getStory(storyKey):null;showModal('Save a lesson',`<div class="field"><label>Lesson or story title *</label><input name="title" required maxlength="100" value="${esc(s?.title||'')}" placeholder="What did you teach?"></div><div class="form-grid"><div class="field"><label>Date *</label><input name="date" type="date" required value="${presetDate||dateISO()}"></div><div class="field"><label>Scripture reference</label><input name="ref" value="${esc(s?.ref||'')}" placeholder="e.g. Luke 15:1–7"></div></div><div class="field"><label>Activity</label><input name="activity" maxlength="140" value="${esc(s?.activity||'')}" placeholder="Craft, game, or discussion"></div><div class="field"><label>Notes for next time</label><textarea name="notes" maxlength="500" placeholder="What went well? What would you like to remember?"></textarea></div>`,'Save lesson',f=>{db.lessons.push({id:crypto.randomUUID(),title:f.get('title').trim(),date:f.get('date'),ref:f.get('ref').trim(),activity:f.get('activity').trim(),notes:f.get('notes').trim()});toast('Lesson saved')})}
function storyModal(key){let s=getStory(key);if(!s)return;let root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal"><div class="story-art modal-art"><img src="images/${esc(s.image)}" alt="Illustration of ${esc(s.title)}"></div><h2>${esc(s.title)}</h2><div class="reference">${esc(s.ref)}</div><p class="story-detail">${esc(s.summary)}</p><div class="panel idea-panel"><b>Big idea</b><p class="story-detail">${esc(s.message||'')}</p></div><div class="panel activity-panel"><b>Activity idea</b><p class="story-detail">${esc(s.activity||'')}</p></div><p class="library-intro">Use the scripture reference to read the full passage in your preferred Bible.</p><div class="modal-actions"><button class="secondary" id="closeStory">Close</button><button class="primary" id="saveStoryLesson">＋ Save as lesson</button></div></div></div>`;root.querySelector('#closeStory').onclick=()=>root.innerHTML='';root.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''};root.querySelector('#saveStoryLesson').onclick=()=>{root.innerHTML='';lessonModal(key)}}
function addStoryModal(){showModal('Add a story to your library',`<div class="field"><label>Story title *</label><input name="title" required maxlength="100" placeholder="Name of the Bible story"></div><div class="field"><label>Scripture reference *</label><input name="ref" required maxlength="100" placeholder="e.g. Acts 9:1–19"></div><div class="field"><label>Short summary *</label><textarea name="summary" required maxlength="500" placeholder="Write a child-friendly summary in your own words"></textarea></div><div class="field"><label>Big idea</label><input name="message" maxlength="200" placeholder="What should children remember?"></div><div class="field"><label>Activity idea</label><input name="activity" maxlength="200" placeholder="A game, craft, or discussion prompt"></div>`,'Add story',f=>{db.customStories.push({title:f.get('title').trim(),ref:f.get('ref').trim(),summary:f.get('summary').trim(),message:f.get('message').trim(),activity:f.get('activity').trim(),image:'creation.svg'});toast('Story added to your library')})}
function exportBackup(){let blob=new Blob([JSON.stringify({app:'BrightSteps',exportedAt:new Date().toISOString(),...db},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`brightsteps-backup-${dateISO()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded')}
function setConnection(){let el=document.getElementById('connectionStatus');if(el){el.textContent=navigator.onLine?'● Online':'● Offline';el.classList.toggle('offline',!navigator.onLine)}}
document.querySelectorAll('.nav-item').forEach(n=>n.onclick=()=>go(n.dataset.page));document.getElementById('quickAdd').onclick=()=>lessonModal();document.getElementById('exportBtn').onclick=exportBackup;document.getElementById('exportTop').onclick=exportBackup;document.getElementById('todayLabel').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();window.addEventListener('online',setConnection);window.addEventListener('offline',setConnection);go('home');setConnection();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
function homeView(){let recent=db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);let latest=recent.find(s=>s.completed),rec=latest&&sessionRecord(latest.id),marks=rec?Object.values(rec.marks):[];let present=marks.filter(m=>m.status==='present').length,late=marks.filter(m=>m.status==='late').length;return `<div class="welcome"><div><h2>Welcome to your classroom 🌿</h2><p>Keep lessons, activities, and every class session in one place.</p></div><div class="welcome-art">📖</div></div><div class="stats"><div class="stat"><div class="stat-top">Children in your class <span class="stat-icon">♡</span></div><div class="stat-num">${db.children.length}</div><div class="stat-note">${AGE_GROUPS.length-1} age groups</div></div><div class="stat"><div class="stat-top">Sessions planned <span class="stat-icon">▦</span></div><div class="stat-num">${db.sessions.length}</div><div class="stat-note">Lessons and roster together</div></div><div class="stat"><div class="stat-top">Last session attendance <span class="stat-icon">✓</span></div><div class="stat-num">${latest?present+late:'—'}</div><div class="stat-note">${latest?`${present} present · ${late} late · ${niceDate(latest.date)}`:'Plan a session to get started'}</div></div></div><div class="grid-two"><div class="panel"><div class="panel-head"><h2>Upcoming sessions</h2><button class="text-button" data-go="calendar">Open calendar →</button></div>${recent.length?recent.map(s=>`<div class="lesson-row"><div class="date-tile"><b>${new Date(s.date+'T12:00:00').getDate()}</b><small>${new Date(s.date+'T12:00:00').toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small></div><div class="row-main"><b>${esc(s.title)}</b><small>${esc(sessionLesson(s)?.title||'No lesson assigned')}</small></div><button class="secondary" data-open-session="${esc(s.id)}">Roster</button></div>`).join(''):'<div class="empty">Plan your first session and assign a Bible lesson.<br><button class="text-button" data-action="newsession">＋ Create a session</button></div>'}</div><div class="panel"><div class="panel-head"><h2>Keep the records together</h2></div><p class="library-intro">Each session links the lesson, age-group roster, attendance, and follow-up remarks.</p><div class="toolbar"><button class="secondary" data-go="reports">Weekly reports →</button><button class="secondary" data-go="guardian">Guardian view →</button></div></div></div>`}
function addChildModal(){showModal('Add a child',`<div class="field"><label>Child’s name *</label><input name="name" required maxlength="70" placeholder="First and last name"></div><div class="form-grid"><div class="field"><label>Age (optional)</label><input name="age" type="number" min="1" max="18" placeholder="e.g. 7"></div><div class="field"><label>Age group</label><select name="ageGroup"><option value="">Assign from age</option>${AGE_GROUPS.map(g=>`<option>${g}</option>`).join('')}</select></div></div><div class="field"><label>Notes (optional)</label><input name="notes" maxlength="100" placeholder="Brief class note"></div>`,'Add child',f=>{let c={id:newId(),name:f.get('name').trim(),age:f.get('age'),ageGroup:f.get('ageGroup')||getAgeGroup({age:f.get('age')}),notes:f.get('notes').trim()};db.children.push(c);toast('Child added to age group')})}
function sessionModal(date=dateISO(),id=''){let old=id?db.sessions.find(s=>s.id===id):null;showModal(old?'Edit class session':'Plan a class session',`<div class="field"><label>Session name *</label><input name="title" required maxlength="80" value="${esc(old?.title||'Sunday Class')}" placeholder="e.g. Sunday School"></div><div class="form-grid"><div class="field"><label>Session date *</label><input name="date" type="date" required value="${esc(old?.date||date)}"></div><div class="field"><label>Assign a lesson</label><select name="lessonId"><option value="">Choose lesson…</option>${db.lessons.map(l=>`<option value="${esc(l.id)}" ${old?.lessonId===l.id?'selected':''}>${esc(l.title)} · ${esc(l.ref||'')}</option>`).join('')}</select></div></div><p class="library-intro">The assigned lesson will appear beside the roster when you take attendance.</p>`,'Save session',f=>{let data={title:f.get('title').trim(),date:f.get('date'),lessonId:f.get('lessonId')};if(old)Object.assign(old,data);else{let s={id:newId(),...data,completed:false};db.sessions.push(s);selectedSessionId=s.id;selectedCalendarDate=s.date}toast('Session saved')})}
function attendanceView(){let s=db.sessions.find(x=>x.id===selectedSessionId)||db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];if(s)selectedSessionId=s.id;let rec=s?sessionRecord(s.id):null;return `<div class="toolbar"><select id="sessionPicker" class="search"><option value="">Choose a class session…</option>${db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<option value="${esc(x.id)}" ${s?.id===x.id?'selected':''}>${niceDate(x.date)} · ${esc(x.title)}</option>`).join('')}</select><button class="primary" data-action="newsession">＋ New session</button>${s?`<button class="secondary" data-edit-session="${esc(s.id)}">Edit session</button>`:''}</div>${s?`<div class="panel session-banner"><div><span class="eyebrow">${niceDate(s.date)}</span><h2>${esc(s.title)}</h2><p>${sessionLesson(s)?`Lesson: ${esc(sessionLesson(s).title)} · ${esc(sessionLesson(s).ref||'')}`:'No lesson assigned yet.'}</p></div><button class="secondary" data-edit-session="${esc(s.id)}">Assign lesson</button></div><div class="panel"><div class="panel-head"><div class="attendance-title"><h2>Mark attendance</h2><span class="pill" id="attendanceCounts">${rec?Object.values(rec.marks).filter(m=>m.status==='present').length:0} present · ${rec?Object.values(rec.marks).filter(m=>m.status==='late').length:0} late</span></div><button class="text-button" id="markAllPresent">Mark all present</button></div>${db.children.length?AGE_GROUPS.map(g=>{let kids=db.children.filter(c=>(c.ageGroup||getAgeGroup(c))===g);if(!kids.length)return '';return `<h3 class="group-heading">${g} <span>${kids.length}</span></h3><div class="table-wrap"><table class="table attendance-table"><thead><tr><th>CHILD</th><th>STATUS</th><th>REMARK</th></tr></thead><tbody>${kids.map(c=>{let mark=rec?.marks?.[c.id]||{};return `<tr><td><div class="person"><span class="avatar">${esc(initials(c.name))}</span><b>${esc(c.name)}</b></div></td><td><select class="status-select" data-child-status="${esc(c.id)}"><option value="" ${!mark.status?'selected':''}>Choose…</option><option value="present" ${mark.status==='present'?'selected':''}>Present</option><option value="late" ${mark.status==='late'?'selected':''}>Late</option><option value="absent" ${mark.status==='absent'?'selected':''}>Absent</option></select></td><td><input class="remark-input" data-child-remark="${esc(c.id)}" value="${esc(mark.remark||'')}" maxlength="180" placeholder="Optional note or follow-up"></td></tr>`}).join('')}</tbody></table></div>`}).join(''):'<div class="empty">Add children to take attendance.</div>'}<button class="primary" id="saveSessionAttendance">Save this session’s attendance</button></div>`:'<div class="panel empty">Create a class session first. Add its date and lesson, then mark the children present, late, or absent.<br><button class="primary" data-action="newsession">＋ Create a class session</button></div>'}`}
function reportsView(){reportDate=document.getElementById('reportDate')?.value||reportDate;let d=new Date(reportDate+'T12:00:00');let monday=new Date(d);monday.setDate(d.getDate()-(d.getDay()+6)%7);let sunday=new Date(monday);sunday.setDate(monday.getDate()+6);let start=dateISO(monday),end=dateISO(sunday),sessions=db.sessions.filter(s=>s.date>=start&&s.date<=end).sort((a,b)=>a.date.localeCompare(b.date));let group=document.getElementById('reportGroup')?.value||'all';let kids=db.children.filter(c=>group==='all'||(c.ageGroup||getAgeGroup(c))===group);let rows=kids.map(c=>{let p=0,l=0,a=0;for(let s of sessions){let m=sessionRecord(s.id)?.marks?.[c.id]?.status;if(m==='present')p++;else if(m==='late')l++;else if(m==='absent'||s.completed)a++}return `<tr><td>${esc(c.name)}</td><td>${esc(c.ageGroup||getAgeGroup(c))}</td><td>${p}</td><td>${l}</td><td>${a}</td></tr>`}).join('');let follow=sessions.flatMap(s=>db.children.filter(c=>sessionRecord(s.id)?.marks?.[c.id]?.status==='absent').map(c=>`<div class="lesson-row"><div class="date-tile"><b>!</b><small>FOLLOW UP</small></div><div class="row-main"><b>${esc(c.name)}</b><small>${esc(c.ageGroup||getAgeGroup(c))} · absent ${niceDate(s.date)} · ${esc(sessionRecord(s.id).marks[c.id].remark||'No remark added')}</small></div></div>`));return `<div class="toolbar"><label class="field compact-field"><span>Choose a date in the week</span><input id="reportDate" type="date" value="${esc(reportDate)}"></label><select id="reportGroup" class="secondary"><option value="all" ${group==='all'?'selected':''}>All age groups</option>${AGE_GROUPS.map(g=>`<option value="${g}" ${group===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="panel"><div class="panel-head"><h2>Weekly class report</h2><span class="pill">${niceDate(start)} – ${niceDate(end)}</span></div>${sessions.length?`<div class="report-summary">${sessions.length} session${sessions.length===1?'':'s'} · ${kids.length} children</div><div class="table-wrap"><table class="table"><thead><tr><th>CHILD</th><th>AGE GROUP</th><th>PRESENT</th><th>LATE</th><th>ABSENT</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">No sessions recorded for this week. Schedule a session in the calendar.</div>'}</div><div class="panel"><div class="panel-head"><h2>Absent children · follow-up list</h2><span class="pill">${follow.length} entries</span></div>${follow.length?follow.join(''):'<div class="empty">No children marked absent in this week’s sessions.</div>'}</div><div class="panel"><div class="panel-head"><h2>Session summary</h2></div>${sessions.length?sessions.map(s=>{let vals=Object.values(sessionRecord(s.id)?.marks||{});return `<div class="lesson-row"><div class="date-tile"><b>${new Date(s.date+'T12:00:00').getDate()}</b><small>${new Date(s.date+'T12:00:00').toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small></div><div class="row-main"><b>${esc(s.title)}</b><small>${esc(sessionLesson(s)?.title||'No lesson assigned')} · ${vals.filter(x=>x.status==='present').length} present · ${vals.filter(x=>x.status==='late').length} late · ${vals.filter(x=>x.status==='absent').length} absent</small></div></div>`}).join(''):'<div class="empty">Session details will appear here.</div>'}</div>`}
function guardianView(){guardianChildId=document.getElementById('guardianChild')?.value||guardianChildId||db.children[0]?.id||'';let child=db.children.find(c=>c.id===guardianChildId);let history=child?db.sessions.filter(s=>s.completed).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12):[];return `<div class="panel guardian-banner"><span class="guardian-icon">♡</span><div><h2>Guardian attendance view</h2><p>Read-only summary for one child.</p></div></div><div class="guardian-warning">This preview is stored on this device and is not protected by guardian sign-in. Before sharing online, the app needs private guardian accounts.</div>${db.children.length?`<div class="toolbar"><label class="field compact-field"><span>Child</span><select id="guardianChild" class="search">${db.children.map(c=>`<option value="${esc(c.id)}" ${c.id===guardianChildId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div>${child?`<div class="panel"><div class="panel-head"><div class="person"><span class="avatar">${esc(initials(child.name))}</span><div><h2>${esc(child.name)}</h2><small>${esc(child.ageGroup||getAgeGroup(child))}</small></div></div><span class="pill">Attendance history</span></div>${history.length?history.map(s=>{let m=sessionMark(s.id,child.id);return `<div class="lesson-row"><div class="date-tile"><b>${new Date(s.date+'T12:00:00').getDate()}</b><small>${new Date(s.date+'T12:00:00').toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small></div><div class="row-main"><b>${esc(sessionLesson(s)?.title||s.title)}</b><small>${esc(sessionLesson(s)?.ref||'Class session')} · ${esc(m.remark||'')}</small></div><span class="status-chip status-${m.status}">${m.status==='late'?'Late':m.status==='present'?'Present':'Absent'}</span></div>`}).join(''):'<div class="empty">No attendance records are available yet.</div>'}</div>`:''}`:'<div class="panel empty">Add children to preview a guardian’s attendance view.</div>'}`}
function wireView(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));document.querySelectorAll('[data-action="addchild"]').forEach(x=>x.onclick=addChildModal);document.querySelectorAll('[data-action="addlesson"]').forEach(x=>x.onclick=()=>lessonModal());document.querySelectorAll('[data-action="newsession"]').forEach(x=>x.onclick=()=>sessionModal(selectedCalendarDate));document.querySelectorAll('[data-edit-session]').forEach(x=>x.onclick=()=>sessionModal(dateISO(),x.dataset.editSession));document.querySelectorAll('[data-action="addstory"]').forEach(x=>x.onclick=addStoryModal);document.querySelectorAll('[data-story]').forEach(x=>x.onclick=()=>storyModal(x.dataset.story));document.querySelectorAll('[data-add-story]').forEach(x=>x.onclick=()=>lessonModal(x.dataset.addStory));document.querySelectorAll('[data-offline]').forEach(x=>x.onclick=()=>{let k=x.dataset.offline;if(db.offlineStories.includes(k))db.offlineStories=db.offlineStories.filter(a=>a!==k);else db.offlineStories.push(k);save();render();toast(db.offlineStories.includes(k)?'Story saved for offline use':'Removed from offline saves')});document.querySelectorAll('[data-day]').forEach(x=>x.onclick=()=>{selectedCalendarDate=x.dataset.day;render()});document.querySelectorAll('[data-open-session]').forEach(x=>x.onclick=()=>{selectedSessionId=x.dataset.openSession;go('attendance')});document.querySelectorAll('[data-delete-child]').forEach(x=>x.onclick=()=>{let id=x.dataset.deleteChild,c=db.children.find(c=>c.id===id);if(c&&confirm(`Remove ${c.name} from your class? Session history will remain.`)){db.children=db.children.filter(c=>c.id!==id);save();render()}});document.querySelectorAll('[data-delete-lesson]').forEach(x=>x.onclick=()=>{db.lessons=db.lessons.filter(l=>l.id!==x.dataset.deleteLesson);save();render();toast('Lesson removed')});let childSearch=document.getElementById('childSearch');if(childSearch)childSearch.oninput=()=>document.querySelectorAll('#childRows tr').forEach(r=>r.hidden=!r.dataset.name?.includes(childSearch.value.toLowerCase()));let ageFilter=document.getElementById('ageFilter');if(ageFilter)ageFilter.onchange=render;let ss=document.getElementById('storySearch');if(ss)ss.oninput=()=>{storyFilter=ss.value;let p=ss.selectionStart;render();let n=document.getElementById('storySearch');n.focus();n.setSelectionRange(p,p)};document.getElementById('webSearch')?.addEventListener('click',()=>openSearch(storyFilter));document.getElementById('webSearchAlways')?.addEventListener('click',()=>openSearch(storyFilter));document.getElementById('prevMonth')?.addEventListener('click',()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);render()});document.getElementById('nextMonth')?.addEventListener('click',()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);render()});document.getElementById('thisMonth')?.addEventListener('click',()=>{calendarMonth=new Date();selectedCalendarDate=dateISO();render()});document.getElementById('addCalendarLesson')?.addEventListener('click',()=>sessionModal(selectedCalendarDate));document.getElementById('addSelectedLesson')?.addEventListener('click',()=>sessionModal(selectedCalendarDate));document.getElementById('sessionPicker')?.addEventListener('change',e=>{selectedSessionId=e.target.value;render()});document.getElementById('markAllPresent')?.addEventListener('click',()=>document.querySelectorAll('[data-child-status]').forEach(x=>x.value='present'));document.getElementById('saveSessionAttendance')?.addEventListener('click',()=>{let s=db.sessions.find(x=>x.id===selectedSessionId);if(!s)return;let marks={};db.children.forEach(c=>{let status=document.querySelector(`[data-child-status="${CSS.escape(c.id)}"]`)?.value||'absent';let remark=document.querySelector(`[data-child-remark="${CSS.escape(c.id)}"]`)?.value.trim()||'';marks[c.id]={status,remark}});let rec=sessionRecord(s.id);if(rec){rec.date=s.date;rec.marks=marks}else db.attendanceRecords.push({sessionId:s.id,date:s.date,marks});s.completed=true;db.attendance=db.attendanceRecords;save();render();toast('Session attendance saved')});document.getElementById('reportDate')?.addEventListener('change',e=>{reportDate=e.target.value;render()});document.getElementById('reportGroup')?.addEventListener('change',render);document.getElementById('guardianChild')?.addEventListener('change',e=>{guardianChildId=e.target.value;render()});document.getElementById('saveAttendance')?.addEventListener('click',()=>toast('Choose a session to mark attendance'))}
function showModal(title,body,submitLabel,submit){let root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal"><h2>${title}</h2><form id="modalForm">${body}<div class="modal-actions"><button type="button" class="secondary" id="cancelModal">Cancel</button><button class="primary">${submitLabel}</button></div></form></div></div>`;root.querySelector('#cancelModal').onclick=()=>root.innerHTML='';root.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''};root.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();let ok=await submit(new FormData(e.target));if(ok!==false){root.innerHTML='';save();render()}}}
function storyCard(s){let saved=db.offlineStories.includes(s.key);return `<article class="story-card"><div class="story-art"><img src="${esc(storyImg(s))}" alt="Illustration: ${esc(s.title)}" loading="lazy"></div><h3>${esc(s.title)}</h3><div class="reference">${esc(s.ref)}</div><p>${esc(s.summary)}</p><div class="big-idea">${esc(s.message||'')}</div><div class="story-actions"><button data-story="${s.key}">Story notes</button><button data-add-story="${s.key}">＋ Lesson</button></div><button class="offline-button ${saved?'saved':''}" data-offline="${s.key}">${saved?'✓ Saved for offline':'↓ Save for offline'}</button></article>`}
function storyModal(key){let s=getStory(key);if(!s)return;let root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal"><div class="story-art modal-art"><img src="${esc(storyImg(s))}" alt="Illustration of ${esc(s.title)}"></div><h2>${esc(s.title)}</h2><div class="reference">${esc(s.ref)}</div><p class="story-detail">${esc(s.summary)}</p><div class="panel idea-panel"><b>Big idea</b><p class="story-detail">${esc(s.message||'')}</p></div><div class="panel activity-panel"><b>Activity idea</b><p class="story-detail">${esc(s.activity||'')}</p></div><p class="library-intro">Use the scripture reference to read the full passage in your preferred Bible.</p><div class="modal-actions"><button class="secondary" id="closeStory">Close</button><button class="primary" id="saveStoryLesson">＋ Save as lesson</button></div></div></div>`;root.querySelector('#closeStory').onclick=()=>root.innerHTML='';root.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''};root.querySelector('#saveStoryLesson').onclick=()=>{root.innerHTML='';lessonModal(key)}}
function addStoryModal(){showModal('Add a story to your library',`<div class="field"><label>Story title *</label><input name="title" required maxlength="100" placeholder="Name of the Bible story"></div><div class="field"><label>Scripture reference *</label><input name="ref" required maxlength="100" placeholder="e.g. Acts 9:1–19"></div><div class="field"><label>Short summary *</label><textarea name="summary" required maxlength="500" placeholder="Write a child-friendly summary in your own words"></textarea></div><div class="field"><label>Big idea</label><input name="message" maxlength="200" placeholder="What should children remember?"></div><div class="field"><label>Activity idea</label><input name="activity" maxlength="200" placeholder="A game, craft, or discussion prompt"></div><div class="field"><label>Optional picture (under 700 KB)</label><input name="picture" type="file" accept="image/*"><small>Pictures you add are stored on this device for offline use.</small></div>`,'Add story',async f=>{let file=f.get('picture'),image='custom.svg';if(file?.size){if(file.size>700000){alert('Please choose an image under 700 KB so it can be saved with your offline records.');return false}image=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}db.customStories.push({title:f.get('title').trim(),ref:f.get('ref').trim(),summary:f.get('summary').trim(),message:f.get('message').trim(),activity:f.get('activity').trim(),image});toast('Story added to your library')})}
function workSamplesPanel(sessionId){let items=db.workSamples.filter(w=>w.sessionId===sessionId);return `<div class="panel"><div class="panel-head"><div><h2>Activities & children’s work</h2><small class="library-intro">Keep a record of crafts, activities, or artwork from this session.</small></div><button class="secondary" data-add-sample="${esc(sessionId)}">＋ Save work sample</button></div>${items.length?`<div class="sample-grid">${items.map(w=>{let c=db.children.find(x=>x.id===w.childId);return `<article class="sample-card">${w.photo?`<img src="${esc(w.photo)}" alt="${esc(w.title)}">`:''}<b>${esc(w.title)}</b><small>${esc(c?.name||'Class activity')}</small><p>${esc(w.note||'')}</p></article>`}).join('')}</div>`:'<div class="empty">No activity or artwork saved for this session yet.</div>'}</div>`}
function workSampleModal(sessionId){showModal('Keep a work sample',`<div class="field"><label>Child (optional)</label><select name="childId"><option value="">Whole class</option>${db.children.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Activity or artwork name *</label><input name="title" required maxlength="90" placeholder="e.g. Creation collage"></div><div class="field"><label>Note</label><textarea name="note" maxlength="240" placeholder="What did the children make or learn?"></textarea></div><div class="field"><label>Picture (optional, under 300 KB)</label><input name="photo" type="file" accept="image/*"><small>Stored in this browser so it’s available offline. Use a small photo for reliable backups.</small></div>`,'Save work sample',async f=>{let file=f.get('photo'),photo='';if(file?.size){if(file.size>300000){alert('Please choose a picture under 300 KB to keep the local backup manageable.');return false}photo=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}db.workSamples.push({id:newId(),sessionId,childId:f.get('childId'),title:f.get('title').trim(),note:f.get('note').trim(),photo});toast('Work sample saved')})}
function attendanceView(){let s=db.sessions.find(x=>x.id===selectedSessionId)||db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];if(s)selectedSessionId=s.id;let rec=s?sessionRecord(s.id):null;return `<div class="toolbar"><select id="sessionPicker" class="search"><option value="">Choose a class session…</option>${db.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<option value="${esc(x.id)}" ${s?.id===x.id?'selected':''}>${niceDate(x.date)} · ${esc(x.title)}</option>`).join('')}</select><button class="primary" data-action="newsession">＋ New session</button>${s?`<button class="secondary" data-edit-session="${esc(s.id)}">Edit session</button>`:''}</div>${s?`<div class="panel session-banner"><div><span class="eyebrow">${niceDate(s.date)}</span><h2>${esc(s.title)}</h2><p>${sessionLesson(s)?`Lesson: ${esc(sessionLesson(s).title)} · ${esc(sessionLesson(s).ref||'')}`:'No lesson assigned yet.'}</p></div><button class="secondary" data-edit-session="${esc(s.id)}">Assign lesson</button></div><div class="panel"><div class="panel-head"><div class="attendance-title"><h2>Mark attendance</h2><span class="pill" id="attendanceCounts">${rec?Object.values(rec.marks).filter(m=>m.status==='present').length:0} present · ${rec?Object.values(rec.marks).filter(m=>m.status==='late').length:0} late</span></div><button class="text-button" id="markAllPresent">Mark all present</button></div>${db.children.length?AGE_GROUPS.map(g=>{let kids=db.children.filter(c=>(c.ageGroup||getAgeGroup(c))===g);if(!kids.length)return '';return `<h3 class="group-heading">${g} <span>${kids.length}</span></h3><div class="table-wrap"><table class="table attendance-table"><thead><tr><th>CHILD</th><th>STATUS</th><th>REMARK</th></tr></thead><tbody>${kids.map(c=>{let mark=rec?.marks?.[c.id]||{};return `<tr><td><div class="person"><span class="avatar">${esc(initials(c.name))}</span><b>${esc(c.name)}</b></div></td><td><select class="status-select" data-child-status="${esc(c.id)}"><option value="" ${!mark.status?'selected':''}>Choose…</option><option value="present" ${mark.status==='present'?'selected':''}>Present</option><option value="late" ${mark.status==='late'?'selected':''}>Late</option><option value="absent" ${mark.status==='absent'?'selected':''}>Absent</option></select></td><td><input class="remark-input" data-child-remark="${esc(c.id)}" value="${esc(mark.remark||'')}" maxlength="180" placeholder="Optional note or follow-up"></td></tr>`}).join('')}</tbody></table></div>`}).join(''):'<div class="empty">Add children to take attendance.</div>'}<button class="primary" id="saveSessionAttendance">Save this session’s attendance</button></div>${workSamplesPanel(s.id)}`:'<div class="panel empty">Create a class session first. Add its date and lesson, then mark the children present, late, or absent.<br><button class="primary" data-action="newsession">＋ Create a class session</button></div>'}`}
document.addEventListener('click',e=>{let b=e.target.closest('[data-add-sample]');if(b)workSampleModal(b.dataset.addSample)});

// Story details support illustrated scene-by-scene teaching, including user-added pictures.
function storyModal(key){let s=getStory(key);if(!s)return;let root=document.getElementById('modalRoot'),frames=s.frames||[];let sceneHtml=frames.length?`<h3 class="group-heading">Tell the story one scene at a time</h3><div class="scene-sequence">${frames.map((f,i)=>`<article class="scene-frame"><img src="${esc(f.image?.startsWith('data:')?f.image:`images/${f.image||'custom.svg'}`)}" alt="${esc(f.title||`Scene ${i+1}`)}"><div class="scene-copy"><b>${esc(f.title||`Scene ${i+1}`)}</b>${f.ref?`<small>${esc(f.ref)}</small>`:''}<p>${esc(f.text||'')}</p></div></article>`).join('')}</div>`:'';let source=s.title.toLowerCase().includes('creation')?`<p class="art-credit">Want more storybook-style Creation pictures? <a href="https://www.freebibleimages.org/illustrations/preschool-creation/" target="_blank" rel="noopener">Browse Sue Bentley’s Creation set at FreeBibleimages ↗</a> Scenes 1–4 use her human-drawn pictures, included unmodified under <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>. The final garden scene is an original hand-coded illustration. All five work offline.</p>`:'';root.innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal story-modal"><div class="story-art modal-art"><img src="${esc(storyImg(s))}" alt="Illustration of ${esc(s.title)}"></div><h2>${esc(s.title)}</h2><div class="reference">${esc(s.ref)}</div><p class="story-detail">${esc(s.summary)}</p>${sceneHtml}${source}<div class="panel idea-panel"><b>Big idea</b><p class="story-detail">${esc(s.message||'')}</p></div><div class="panel activity-panel"><b>Activity idea</b><p class="story-detail">${esc(s.activity||'')}</p></div><p class="library-intro">Use the scripture reference to read the full passage in your preferred Bible.</p><div class="modal-actions"><button class="secondary" id="closeStory">Close</button><button class="primary" id="saveStoryLesson">＋ Save as lesson</button></div></div></div>`;root.querySelector('#closeStory').onclick=()=>root.innerHTML='';root.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''};root.querySelector('#saveStoryLesson').onclick=()=>{root.innerHTML='';lessonModal(key)}}

function addStoryModal(){showModal('Add a story to your library',`<div class="field"><label>Story title *</label><input name="title" required maxlength="100" placeholder="Name of the Bible story"></div><div class="field"><label>Scripture reference *</label><input name="ref" required maxlength="100" placeholder="e.g. Acts 9:1–19"></div><div class="field"><label>Short summary *</label><textarea name="summary" required maxlength="500" placeholder="Write a child-friendly summary in your own words"></textarea></div><div class="field"><label>Big idea</label><input name="message" maxlength="200" placeholder="What should children remember?"></div><div class="field"><label>Activity idea</label><input name="activity" maxlength="200" placeholder="A game, craft, or discussion prompt"></div><div class="field"><label>Story pictures (up to 5, each under 350 KB)</label><input name="pictures" type="file" accept="image/*" multiple><small>Add several pictures to tell the story step by step. Your pictures are saved on this device for offline use.</small></div><div class="field"><label>Scene captions (one per line)</label><textarea name="captions" maxlength="700" placeholder="God made the light…&#10;God made the sky and waters…"></textarea></div>`,'Add story',async f=>{let files=[...f.getAll('pictures')].filter(x=>x.size);if(files.length>5||files.some(x=>x.size>350000)||files.reduce((a,x)=>a+x.size,0)>900000){alert('Choose up to 5 pictures, each under 350 KB and 900 KB total, to fit offline storage.');return false}let captions=String(f.get('captions')||'').split(/\r?\n/);let frames=await Promise.all(files.map((file,i)=>new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve({title:`Scene ${i+1}`,ref:'',text:captions[i]?.trim()||'',image:r.result});r.onerror=reject;r.readAsDataURL(file)})));let story={title:f.get('title').trim(),ref:f.get('ref').trim(),summary:f.get('summary').trim(),message:f.get('message').trim(),activity:f.get('activity').trim(),image:frames[0]?.image||'custom.svg',frames};db.customStories.push(story);toast('Story added with its picture sequence')})}


// Make every story illustration accessible as an enlarged, keyboard-friendly picture.
function storyCard(s){let saved=db.offlineStories.includes(s.key),src=storyImg(s),alt='Illustration: '+s.title;return `<article class="story-card"><div class="story-art"><img src="${esc(src)}" alt="${esc(alt)}" data-zoom-src="${esc(src)}" data-zoom-alt="${esc(alt)}" role="button" tabindex="0" aria-label="Enlarge picture: ${esc(s.title)}" loading="lazy"><span class="zoom-hint">Tap to enlarge ⤢</span></div><h3>${esc(s.title)}</h3><div class="reference">${esc(s.ref)}</div><p>${esc(s.summary)}</p><div class="big-idea">${esc(s.message||'')}</div><div class="story-actions"><button data-story="${s.key}">Story notes</button><button data-add-story="${s.key}">＋ Lesson</button></div><button class="offline-button ${saved?'saved':''}" data-offline="${s.key}">${saved?'✓ Saved for offline':'↓ Save for offline'}</button></article>`}
function storyModal(key){let s=getStory(key);if(!s)return;let root=document.getElementById('modalRoot'),frames=s.frames||[];let sceneHtml=frames.length?`<h3 class="group-heading">Tell the story one scene at a time</h3><div class="scene-sequence">${frames.map((f,i)=>{let src=f.image?.startsWith('data:')?f.image:`images/${f.image||'custom.svg'}`,alt=f.title||`Scene ${i+1}`;return `<article class="scene-frame"><img src="${esc(src)}" alt="${esc(alt)}" data-zoom-src="${esc(src)}" data-zoom-alt="${esc(alt)}" role="button" tabindex="0" aria-label="Enlarge picture: ${esc(alt)}"><span class="zoom-hint">Tap to enlarge ⤢</span><div class="scene-copy"><b>${esc(alt)}</b>${f.ref?`<small>${esc(f.ref)}</small>`:''}<p>${esc(f.text||'')}</p></div></article>`}).join('')}</div>`:'';let src=storyImg(s),alt='Illustration of '+s.title,source=s.title.toLowerCase().includes('creation')?`<p class="art-credit">Want more storybook-style Creation pictures? <a href="https://www.freebibleimages.org/illustrations/preschool-creation/" target="_blank" rel="noopener">Browse Sue Bentley’s Creation set at FreeBibleimages ↗</a>. Scenes 1–4 use her human-drawn pictures, included unmodified under <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>. The final garden scene is an original hand-coded illustration. All five work offline.</p>`:'';root.innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal story-modal"><div class="story-art modal-art"><img src="${esc(src)}" alt="${esc(alt)}" data-zoom-src="${esc(src)}" data-zoom-alt="${esc(alt)}" role="button" tabindex="0" aria-label="Enlarge picture: ${esc(s.title)}"><span class="zoom-hint">Tap to enlarge ⤢</span></div><h2>${esc(s.title)}</h2><div class="reference">${esc(s.ref)}</div><p class="story-detail">${esc(s.summary)}</p>${sceneHtml}${source}<div class="panel idea-panel"><b>Big idea</b><p class="story-detail">${esc(s.message||'')}</p></div><div class="panel activity-panel"><b>Activity idea</b><p class="story-detail">${esc(s.activity||'')}</p></div><p class="library-intro">Use the scripture reference to read the full passage in your preferred Bible.</p><div class="modal-actions"><button class="secondary" id="closeStory">Close</button><button class="primary" id="saveStoryLesson">＋ Save as lesson</button></div></div></div>`;root.querySelector('#closeStory').onclick=()=>root.innerHTML='';root.querySelector('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''};root.querySelector('#saveStoryLesson').onclick=()=>{root.innerHTML='';lessonModal(key)}}
function openStoryPicture(src,alt,trigger){let root=document.getElementById('modalRoot'),layer=document.createElement('div');layer.className='picture-zoom-backdrop';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label',alt);layer.innerHTML=`<div class="picture-zoom-viewer"><button class="picture-zoom-close" type="button" aria-label="Close enlarged picture">×</button><img src="${esc(src)}" alt="${esc(alt)}"><p>Click or tap outside the picture to close</p></div>`;root.appendChild(layer);let close=()=>{layer.remove();document.removeEventListener('keydown',onKey);trigger?.focus()};let onKey=e=>{if(e.key==='Escape')close()};layer.querySelector('.picture-zoom-close').onclick=close;layer.addEventListener('click',e=>{if(e.target===layer)close()});layer.querySelector('img').onclick=e=>e.stopPropagation();document.addEventListener('keydown',onKey);layer.querySelector('button').focus()}
document.addEventListener('click',e=>{let img=e.target.closest('[data-zoom-src]');if(img)openStoryPicture(img.dataset.zoomSrc,img.dataset.zoomAlt||img.alt,img)});document.addEventListener('keydown',e=>{let img=e.target.closest?.('[data-zoom-src]');if(img&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openStoryPicture(img.dataset.zoomSrc,img.dataset.zoomAlt||img.alt,img)}});

// Attach the five bundled, offline-ready scene illustrations to each built-in story.
function allStories(){return [...STORY_DATA.map((s,i)=>({...s,frames:BRIGHTSTEPS_STORY_SCENES[s.title]||s.frames,key:'b'+i,custom:false})),...db.customStories.map((s,i)=>({...s,key:'c'+i,custom:true,image:s.frames?.[0]?.image||s.image||'custom.svg'}))]}
